{
  "name": "bt_prepare_event_packet",
  "confidence": "medium",
  "docstring": "If the selected BT connection/event context is present, build an 18-byte custom BT event packet containing the context subtype, an incremented sequence value, and an 8-byte ke_process_event payload, returning the packet length; otherwise return the absent context result (0).",
  "subsystem": "bt",
  "var_renames": {
    "result": "event_ctx",
    "v5": "pkt",
    "v6": "old_seq",
    "v7": "seq",
    "v8": "seq_ptr",
    "v12": "payload_ptr",
    "v13": "zero_ptr",
    "v14": "event_result"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "BT connection/device index used to select the event context"
    },
    {
      "offset": 72,
      "meaning": "64-bit sequence/timestamp counter copied to the packet and incremented"
    },
    {
      "offset": 97,
      "meaning": "byte-valued event subtype/state written into packet offset 2"
    }
  ]
}
